# Function to find girth using BFS
def girth(graph, n):
    min_cycle = float('inf')
    for start in range(n):
        queue = deque([(start, -1, 0)])  # node, parent, dist
        dist = [-1] * n
        dist[start] = 0
        while queue:
            node, parent, d = queue.popleft()
            for nei in graph[node]:
                if nei == parent:
                    continue
                if dist[nei] == -1:
                    dist[nei] = d + 1
                    queue.append((nei, node, d+1))
                elif dist[nei] >= 0:
                    cycle = d + dist[nei] + 1
                    if cycle < min_cycle:
                        min_cycle = cycle
    return min_cycle if min_cycle != float('inf') else 0

