# To check chromatic number or if 5-colorable, since small, can try to color with 5 colors
# Simple backtrack colorer
def is_safe(v, color, c):
    for nei in adj[v]:
        if color[nei] == c:
            return False
    return True

def graph_coloring_util(color, c, v, V):
    if v == V:
        return True
    for col in range(1, c+1):
        if is_safe(v, color, col):
            color[v] = col
            if graph_coloring_util(color, c, v+1, V):
                return True
            color[v] = 0
    return False

def is_k_colorable(k):
    color = [0] * 9
    return graph_coloring_util(color, k, 0, 9)

